v30Router.get('/pro/opportunities/:id/matches',async(req,res)=>{try{const o=(await pool.query('SELECT * FROM v30_pro_opportunities WHERE id=$1',[req.params.id])).rows[0];if(!o)return res.status(404).json({error:'opportunity_not_found'});const q=await pool.query(`SELECT p.*,((CASE WHEN p.territory_key=$2 THEN 35 ELSE 0 END)+(SELECT COUNT(*) FROM unnest(p.specialties) s JOIN unnest($3::text[]) a ON lower(s)=lower(a))*15+(SELECT COUNT(*) FROM unnest(p.audiences) s JOIN unnest($4::text[]) a ON lower(s)=lower(a))*10) AS match_score FROM v30_pro_profiles p WHERE p.active=true AND p.id<>$5 AND ($2 IS NULL OR p.territory_key=$2) ORDER BY match_score DESC,p.verified DESC LIMIT 20`,[o.id,o.territory_key,o.specialties,o.audiences,o.source_pro_id]);const matches=q.rows.map(x=>({...x,match_score:Math.min(100,Number(x.match_score)),reasons:[x.territory_key===o.territory_key?'Territoire correspondant':null,x.specialties.some(s=>o.specialties.map(a=>a.toLowerCase()).includes(s.toLowerCase()))?'Spécialités compatibles':null,x.audiences.some(s=>o.audiences.map(a=>a.toLowerCase()).includes(s.toLowerCase()))?'Publics compatibles':null].filter(Boolean)}));res.json({opportunity:o,matches})}catch(e){res.status(500).json({error:e.message})}});



v30Router.post('/pro/b2b/calls/:id/award',async(req,res)=>{const client=await pool.connect();try{const {sourceProId,responseId}=req.body;if(!sourceProId||!responseId)return res.status(400).json({error:'owner_response_required'});await client.query('BEGIN');const c=(await client.query('SELECT * FROM v30_b2b_calls WHERE id=$1 FOR UPDATE',[req.params.id])).rows[0];if(!c)return res.status(404).json({error:'call_not_found'});if(String(c.source_pro_id)!==String(sourceProId))return res.status(403).json({error:'not_owner'});const rr=(await client.query('SELECT * FROM v30_b2b_responses WHERE id=$1 AND call_id=$2',[responseId,req.params.id])).rows[0];if(!rr)return res.status(404).json({error:'response_not_found'});await client.query("UPDATE v30_b2b_responses SET status='rejected' WHERE call_id=$1 AND id<>$2 AND status IN ('submitted','shortlisted')",[req.params.id,responseId]);await client.query("UPDATE v30_b2b_responses SET status='accepted' WHERE id=$1",[responseId]);await client.query("UPDATE v30_b2b_calls SET status='awarded' WHERE id=$1",[req.params.id]);await client.query("INSERT INTO v30_b2b_call_events(call_id,actor_pro_id,event_type,response_id) VALUES($1,$2,'accepted',$3)",[req.params.id,sourceProId,responseId]);await client.query('COMMIT');res.json({ok:true,callId:req.params.id,acceptedResponseId:responseId})}catch(e){await client.query('ROLLBACK');res.status(500).json({error:e.message})}finally{client.release()}});
v30Router.patch('/pro/b2b/calls/:id',async(req,res)=>{try{const {sourceProId,status,responseDeadline,title,description}=req.body;const c=(await pool.query('SELECT * FROM v30_b2b_calls WHERE id=$1',[req.params.id])).rows[0];if(!c)return res.status(404).json({error:'call_not_found'});if(sourceProId&&String(c.source_pro_id)!==String(sourceProId))return res.status(403).json({error:'not_owner'});const q=await pool.query('UPDATE v30_b2b_calls SET status=COALESCE($1,status),response_deadline=COALESCE($2,response_deadline),title=COALESCE($3,title),description=COALESCE($4,description) WHERE id=$5 RETURNING *',[status,responseDeadline,title,description,req.params.id]);res.json({call:q.rows[0]})}catch(e){res.status(500).json({error:e.message})}});
