v30Router.get('/pro/:id/recommendations',async(req,res)=>{try{const p=(await pool.query('SELECT * FROM v30_pro_profiles WHERE id=$1 AND active=true',[req.params.id])).rows[0];if(!p)return res.status(404).json({error:'professional_not_found'});const q=await pool.query(`SELECT x.*,((CASE WHEN x.territory_key=$2 THEN 35 ELSE 0 END)+(SELECT COUNT(*) FROM unnest(x.specialties) s JOIN unnest($3::text[]) a ON lower(s)=lower(a))*15+(SELECT COUNT(*) FROM unnest(x.audiences) s JOIN unnest($4::text[]) a ON lower(s)=lower(a))*10+(CASE WHEN x.pro_type<>$5 THEN 10 ELSE 0 END)) AS match_score FROM v30_pro_profiles x WHERE x.active=true AND x.id<>$1 AND x.country_iso3=$6 ORDER BY match_score DESC,x.verified DESC LIMIT 20`,[p.id,p.territory_key,p.specialties,p.audiences,p.pro_type,p.country_iso3]);const recommendations=q.rows.map(x=>({...x,match_score:Math.min(100,Number(x.match_score)),reasons:[x.territory_key===p.territory_key?'Même territoire':null,x.pro_type!==p.pro_type?'Métiers complémentaires':null,x.specialties.some(s=>p.specialties.map(a=>a.toLowerCase()).includes(s.toLowerCase()))?'Spécialités compatibles':null,x.audiences.some(s=>p.audiences.map(a=>a.toLowerCase()).includes(s.toLowerCase()))?'Publics compatibles':null].filter(Boolean)}));res.json({professional:p,recommendations})}catch(e){res.status(500).json({error:e.message})}});

