v30Router.get('/pro/b2b/calls/:id/matches',async(req,res)=>{try{const c=(await pool.query('SELECT * FROM v30_b2b_calls WHERE id=$1',[req.params.id])).rows[0];if(!c)return res.status(404).json({error:'call_not_found'});const q=await pool.query(`SELECT p.*,((CASE WHEN p.territory_key=$2 THEN 30 ELSE 0 END)+(SELECT COUNT(*) FROM unnest(p.specialties) s JOIN unnest($3::text[]) a ON lower(s)=lower(a))*15+(SELECT COUNT(*) FROM unnest(p.audiences) s JOIN unnest($4::text[]) a ON lower(s)=lower(a))*10+(CASE WHEN p.country_iso3=ANY($5::text[]) THEN 15 ELSE 0 END)+(CASE WHEN p.pro_type<>$6 THEN 10 ELSE 0 END)) AS match_score FROM v30_pro_profiles p WHERE p.active=true AND p.id<>$7 ORDER BY match_score DESC,p.verified DESC LIMIT 50`,[c.id,c.territory_key,c.specialties,c.audiences,c.target_countries,c.source_pro_id,c.source_pro_id]);const matches=q.rows.map(x=>({...x,match_score:Math.min(100,Number(x.match_score)),reasons:[x.territory_key===c.territory_key?'Territoire correspondant':null,x.specialties.some(s=>c.specialties.map(a=>a.toLowerCase()).includes(s.toLowerCase()))?'Spécialités compatibles':null,x.audiences.some(s=>c.audiences.map(a=>a.toLowerCase()).includes(s.toLowerCase()))?'Publics compatibles':null,x.pro_type!==c.call_type?'Profil professionnel pertinent':null].filter(Boolean)}));res.json({call:c,matches})}catch(e){res.status(500).json({error:e.message})}});
v30Router.post('/pro/b2b/calls/:id/responses',async(req,res)=>{try{const {responderProId,message,proposal={},matchScore=null}=req.body;if(!responderProId||!message)return res.status(400).json({error:'responder_message_required'});const q=await pool.query('INSERT INTO v30_b2b_responses(call_id,responder_pro_id,message,proposal,match_score) VALUES($1,$2,$3,$4,$5) ON CONFLICT(call_id,responder_pro_id) DO UPDATE SET message=EXCLUDED.message,proposal=EXCLUDED.proposal,match_score=EXCLUDED.match_score,status=\'submitted\' RETURNING *',[req.params.id,responderProId,message,proposal,matchScore]);res.status(201).json({response:q.rows[0]})}catch(e){res.status(500).json({error:e.message})}});
v30Router.get('/pro/b2b/calls/:id/responses',async(req,res)=>{try{const q=await pool.query('SELECT r.*,p.name responder_name,p.specialties,p.verified FROM v30_b2b_responses r JOIN v30_pro_profiles p ON p.id=r.responder_pro_id WHERE r.call_id=$1 ORDER BY COALESCE(r.match_score,0) DESC,r.created_at',[req.params.id]);res.json({responses:q.rows})}catch(e){res.status(500).json({error:e.message})}});
