v30Router.get('/pro/:id/matches',async(req,res)=>{try{const p=(await pool.query('SELECT * FROM v30_pro_profiles WHERE id=$1 AND active=true',[req.params.id])).rows[0];if(!p)return res.status(404).json({error:'professional_not_found'});const q=await pool.query(`SELECT t.*,n.relationship,n.score,n.reasons FROM v30_pro_network_links n JOIN v30_pro_profiles t ON t.id=n.target_pro_id WHERE n.source_pro_id=$1 AND t.active=true ORDER BY n.score DESC`,[p.id]);res.json({professional:p,matches:q.rows})}catch(e){res.status(500).json({error:e.message})}});
